import{_ as e,a,b as o,c as r,d as i,e as l,f as s,g as n}from"./chunks/update-robot-usb-5.Bdu86dZI.js";import{_ as c,o as d,c as p,a5 as g}from"./chunks/framework.DGp912Ge.js";const _=JSON.parse('{"title":"USB로 소프트웨어 업데이트","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/usb-software-update.md","filePath":"ko/manual/gui/usb-software-update.md","lastUpdated":1785806767000}'),m={name:"ko/manual/gui/usb-software-update.md"};function u(f,t,b,h,U,x){return d(),p("div",null,[...t[0]||(t[0]=[g('<h1 id="usb로-소프트웨어-업데이트" tabindex="-1">USB로 소프트웨어 업데이트 <a class="header-anchor" href="#usb로-소프트웨어-업데이트" aria-label="Permalink to &quot;USB로 소프트웨어 업데이트&quot;">​</a></h1><p>인터넷이 연결되지 않는 폐쇄망 환경에서 USB 메모리로 GUI와 로봇 소프트웨어를 업데이트하는 방법을 안내합니다. 인터넷이 되는 PC에서 USB에 설치 파일을 담아, 스팀덱이나 태블릿에 연결해 업데이트합니다.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>USB 업데이트는 <strong>인터넷 연결만</strong> 대체합니다. 로봇 소프트웨어를 업데이트하려면 GUI가 <strong>로봇과 Wi-Fi로 연결</strong>되어 있어야 합니다. GUI 앱만 설치할 때는 로봇 연결이 필요하지 않습니다.</p></div></div><h2 id="prepare-usb" tabindex="-1">1단계. USB에 설치 파일 준비 <a class="header-anchor" href="#prepare-usb" aria-label="Permalink to &quot;1단계. USB에 설치 파일 준비 {#prepare-usb}&quot;">​</a></h2><p>인터넷이 되는 PC에서 USB 메모리를 연결하고, 최상위에 <code>RBQGUI</code> 폴더를 만듭니다. 그 안에 설치할 버전 이름으로 <code>v{버전}</code> 폴더를 만듭니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+e+'" alt="USB의 RBQGUI 폴더 안에 버전별 폴더" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">RBQGUI 폴더 안의 버전 폴더</figcaption></figure><p>버전 폴더 안에 해당 버전의 파일 두 개를 내려받아 넣습니다. 두 파일 모두 <a href="/RBQ/ko/manual/downloads/">다운로드</a> 페이지에서 받으실 수 있습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">파일</th><th style="text-align:left;">용도</th><th style="text-align:left;">받는 곳</th></tr></thead><tbody><tr><td style="text-align:left;"><code>RBQ-{버전}.tar.gz</code></td><td style="text-align:left;">로봇 소프트웨어</td><td style="text-align:left;">릴리스의 <code>Source code (tar.gz)</code></td></tr><tr><td style="text-align:left;"><code>RBQGUI.apk</code></td><td style="text-align:left;">GUI 앱</td><td style="text-align:left;">릴리스 첨부 파일</td></tr></tbody></table><figure style="margin-top:1rem;text-align:center;"><img src="'+a+'" alt="버전 폴더 안의 tar.gz 파일과 apk 파일" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">버전 폴더 안의 설치 파일</figcaption></figure><p>여러 버전을 미리 담아 두면 현장에서 원하는 버전을 골라 설치할 수 있습니다.</p><h2 id="scan-usb" tabindex="-1">2단계. USB 연결 후 버전 검색 <a class="header-anchor" href="#scan-usb" aria-label="Permalink to &quot;2단계. USB 연결 후 버전 검색 {#scan-usb}&quot;">​</a></h2><p>준비한 USB를 업데이트할 스팀덱 또는 태블릿에 연결한 뒤, <code>Software Update</code> 화면에서 <strong><code>USB</code></strong> 버튼을 누릅니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+o+'" alt="Software Update 화면의 USB 버튼" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">USB 버튼</figcaption></figure><p>USB를 검색하면 로그 창에 찾은 버전 개수가 표시됩니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+r+'" alt="USB 검색 결과가 로그에 표시된 화면" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">USB 검색 완료</figcaption></figure><h2 id="select-version" tabindex="-1">3단계. 설치할 버전 선택 <a class="header-anchor" href="#select-version" aria-label="Permalink to &quot;3단계. 설치할 버전 선택 {#select-version}&quot;">​</a></h2><p>버전 드롭다운을 열고 설치할 버전을 선택합니다. USB에서 찾은 버전에는 <strong><code>[USB]</code></strong> 표시가 붙습니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+i+'" alt="[USB] 표시가 붙은 버전 목록" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">USB에서 찾은 버전 선택</figcaption></figure><p>여기까지는 GUI 업데이트와 로봇 업데이트가 동일합니다. 이후는 목적에 따라 나뉩니다.</p><h2 id="install-gui" tabindex="-1">4단계(GUI). GUI 앱 설치 <a class="header-anchor" href="#install-gui" aria-label="Permalink to &quot;4단계(GUI). GUI 앱 설치 {#install-gui}&quot;">​</a></h2><p><strong><code>Install App</code></strong> 을 누르면 USB의 <code>RBQGUI.apk</code> 로 GUI 앱이 설치됩니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+l+'" alt="Install App 버튼" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Install App</figcaption></figure><p>설치가 끝나면 화면 상단 <code>Current Software Version</code> 의 <code>RBQGUI</code> 값이 설치한 버전으로 바뀐 것을 확인합니다.</p><h2 id="update-robot" tabindex="-1">4단계(로봇). 로봇 소프트웨어 전송 <a class="header-anchor" href="#update-robot" aria-label="Permalink to &quot;4단계(로봇). 로봇 소프트웨어 전송 {#update-robot}&quot;">​</a></h2><p><strong><code>Update Robot</code></strong> 을 누르면 USB의 <code>RBQ-{버전}.tar.gz</code> 가 기기 내부로 복사된 뒤 로봇으로 전송됩니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+s+'" alt="Update Robot 버튼" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Update Robot</figcaption></figure><p>전송이 끝나면 성공 메시지와 함께 <strong><code>Restart Robot</code></strong> 버튼이 나타납니다. 로그에서 USB 복사 → 로봇 전송 순서를 확인할 수 있습니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+n+'" alt="전송 완료 후 나타난 Restart Robot 버튼" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">전송 완료 · Restart Robot</figcaption></figure><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>재시작 전에 로봇을 <strong>앉은 자세</strong>로 두고, 재시작이 끝날 때까지 움직이지 마세요.</p></div></div><p><code>Restart Robot</code> 으로 로봇을 재시작한 뒤, <code>Current Software Version</code> 의 <code>ROBOT</code> 값이 설치한 버전으로 바뀐 것을 확인합니다.</p><h2 id="참고-주의사항" tabindex="-1">참고 / 주의사항 <a class="header-anchor" href="#참고-주의사항" aria-label="Permalink to &quot;참고 / 주의사항&quot;">​</a></h2><ul><li>버전 폴더 이름은 <code>v</code> 로 시작해야 하며, 그 안의 <code>tar.gz</code> 파일 이름의 버전과 일치해야 합니다.</li><li>로봇 업데이트는 GUI가 로봇과 연결된 상태에서만 가능합니다. GUI 앱 설치는 로봇 연결 없이도 가능합니다.</li><li>업데이트 중 <code>EMERGENCY</code> 가 표시되면 즉시 안전을 확인하세요.</li></ul><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">링크</th></tr></thead><tbody><tr><td style="text-align:left;">인터넷으로 GUI 업데이트</td><td style="text-align:left;"><a href="/RBQ/ko/manual/gui/gui-software-update.html">GUI 소프트웨어 업데이트</a></td></tr><tr><td style="text-align:left;">인터넷으로 로봇 업데이트</td><td style="text-align:left;"><a href="/RBQ/ko/manual/gui/robot-software-update.html">로봇 소프트웨어 업데이트</a></td></tr></tbody></table>',34)])])}const S=c(m,[["render",u]]);export{_ as __pageData,S as default};
